// {{ .Name }} — generated by rda from the web-nodejs template.
//
// A small message-wall demo that shows off:
//   1. PostgreSQL binding (env vars projected from the SBS Secret).
//   2. Prometheus metrics on /metrics (HTTP duration histogram +
//      domain counters/gauges).
//   3. Optional Dex (OIDC) login when DEX_PUBLIC_URL is set —
//      browser-side login via oidc-client-ts; auth-required.
//
// The Postgres binding is read from env vars projected by the rda
// library helper (services[].binding=db => DB_HOST, DB_PORT,
// DB_USERNAME, DB_PASSWORD, DB_DATABASE). To use a different binding
// name, set DB_BINDING=<binding> as an env override (uppercased).
//
// Dex is opt-in: only when DEX_PUBLIC_URL is set (typically projected
// from a `services[].type=dex` binding via passthrough). Without it
// the app skips auth and is open.

const http = require('http');
const { Client } = require('pg');
const promClient = require('prom-client');
const crypto = require('crypto');
const { URL, URLSearchParams } = require('url');
// jose: pure-JS, lightweight JWKS fetcher + JWT verifier. Imported
// dynamically inside the OIDC bootstrap to keep startup fast when
// auth is disabled (the dep tree is ~50 modules).
let jose = null;

const PORT = parseInt(process.env.PORT || '8080');

// ─────────────────────────────────────────────
// 🎨 Change this color, save, see it update!
const ACCENT_COLOR = "#736def";
// ─────────────────────────────────────────────

// ─── OIDC SSO (optional) ─────────────────────
// Reads <AUTH_BINDING>_PUBLIC_URL from the binding-secret. Default binding
// name is "auth"; override via AUTH_BINDING=<name> to read from a different
// binding (e.g. binding=idp → IDP_PUBLIC_URL). Auto-derived from the dex
// chart's ingress.host (or in-cluster URL if no ingress) — no manual edit
// needed in deploy/values.yaml.
// AUTH_BINDING may contain dashes (e.g. 'auth-prod'). The bundle's
// binding-secret helper projects env vars with dashes converted to
// underscores (AUTH_PROD_*), so we apply the same normalisation when
// computing the lookup prefix. Without this, a dashed binding name
// silently disables OIDC (the env vars exist but under names the app
// never reads).
const authPrefix = (process.env.AUTH_BINDING || 'AUTH').toUpperCase().replace(/-/g, '_');
const AUTH_PUBLIC_URL = process.env[`${authPrefix}_PUBLIC_URL`] || '';
// AUTH_URL is the in-cluster URL (auth-binding-secret host:port). Used
// for JWKS fetch + token-exchange POST since localtest.me ingresses
// don't resolve from inside the pod. AUTH_PUBLIC_URL is what the
// browser hits.
const AUTH_URL = process.env[`${authPrefix}_URL`] || '';
// AUTH_ISSUER is what tokens claim in their `iss` field — must match
// the chart's dex.config.issuer. Auto-derived alongside AUTH_PUBLIC_URL
// (bundle 0.11.27+).
const AUTH_ISSUER = process.env[`${authPrefix}_ISSUER`] || AUTH_PUBLIC_URL;
// Bundle 0.11.32+ projects <authPrefix>_CLIENT_ID via the binding-secret
// (read from dex.config.staticClients[0].id post-render). Fallback to legacy
// OIDC_CLIENT_ID for projects predating that scaffold. 'message-wall' is the
// last-resort default (neither env set + dex unconfigured).
const OIDC_CLIENT_ID = process.env[`${authPrefix}_CLIENT_ID`] || process.env.OIDC_CLIENT_ID || 'message-wall';
// OIDC_CLIENT_SECRET is required for the /login → /auth/callback browser
// flow (OAuth2 code grant). The Bearer path doesn't need it. Set via
// suse-library.env or project from a Secret. Empty → /login returns 503.
// Bundle 0.11.32+ projects <authPrefix>_CLIENT_SECRET via the binding-secret
// (read from dex.config.staticClients[0].secret). Fallback to legacy
// OIDC_CLIENT_SECRET for projects predating that scaffold. Empty → /login
// returns 503 with a remediation hint.
const OIDC_CLIENT_SECRET = process.env[`${authPrefix}_CLIENT_SECRET`] || process.env.OIDC_CLIENT_SECRET || '';
const SESSION_COOKIE_NAME = process.env.SESSION_COOKIE_NAME || 'id_token';
const STATE_COOKIE_NAME = 'oidc_state';
// Holds the JWKS fetcher once jose is loaded + AUTH_URL is set. Keep
// outside any one request handler so the keyset cache (HTTP TTL handled
// by jose) is shared across requests.
let jwksFetcher = null;
// Back-compat alias: older code (and anyone who copy-pasted the
// pre-0.11.27 template) still references DEX_PUBLIC_URL. Keep it
// working when AUTH_PUBLIC_URL is set.
const DEX_PUBLIC_URL = AUTH_PUBLIC_URL;
// ─────────────────────────────────────────────

// ─── Prometheus metrics ──────────────────────
promClient.collectDefaultMetrics();

const httpDuration = new promClient.Histogram({
  name: 'app_http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'path', 'status'],
  buckets: [0.005, 0.01, 0.05, 0.1, 0.5, 1],
});
const messagesPosted = new promClient.Counter({
  name: 'app_messages_posted_total',
  help: 'Total number of messages posted',
});
const messagesDeleted = new promClient.Counter({
  name: 'app_messages_deleted_total',
  help: 'Total number of bulk deletes',
});
const messagesCurrent = new promClient.Gauge({
  name: 'app_messages_count',
  help: 'Current number of messages in the database',
});
// ────────────────────────────────────────────────

// Default binding name is "db". Override via DB_BINDING= to use a
// differently-named binding (the prefix is uppercased to find env vars).
const dbPrefix = (process.env.DB_BINDING || 'DB').toUpperCase();
const env = (suffix, fallback) => process.env[`${dbPrefix}_${suffix}`] || fallback;

const client = new Client({
  host: env('HOST'),
  port: parseInt(env('PORT', '5432')),
  user: env('USERNAME'),
  password: env('PASSWORD'),
  database: env('DATABASE'),
});

function usernameFromCookie(req) {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies[SESSION_COOKIE_NAME] || '';
  if (!token) return '';
  const parts = token.split('.');
  if (parts.length < 2) return '';
  try {
    const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString());
    return payload.preferred_username || payload.name || payload.email || 'user';
  } catch { return ''; }
}

const html = (req) => {
  const username = AUTH_PUBLIC_URL ? usernameFromCookie(req) : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{{ .Name }} · Message Wall</title>
  <link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>📬</text></svg>">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    :root { --accent: ${ACCENT_COLOR}; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
      background: #0f172a; color: #e2e8f0; min-height: 100vh; display: flex;
      flex-direction: column; align-items: center; }
    header { width: 100%; padding: 2rem; text-align: center;
      background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
      border-bottom: 1px solid #1e293b; }
    header h1 { font-size: 1.8rem; font-weight: 700; color: var(--accent); }
    header p { color: #64748b; margin-top: 0.4rem; font-size: 0.9rem; }
    .info-bar { display: flex; gap: 1.5rem; justify-content: center; margin-top: 1rem; flex-wrap: wrap; }
    .info-pill { display: flex; align-items: center; gap: 0.4rem; background: #1e293b;
      padding: 0.35rem 0.8rem; border-radius: 999px; font-size: 0.75rem; color: #94a3b8;
      border: 1px solid #334155; }
    .info-pill .dot { width: 6px; height: 6px; border-radius: 50%; background: #22c55e;
      animation: pulse 2s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
    main { width: 100%; max-width: 640px; padding: 1.5rem; flex: 1; }
    .compose { display: flex; gap: 0.5rem; margin-bottom: 1.5rem; }
    .compose input[type="text"] { flex: 1; padding: 0.75rem 1rem; border-radius: 0.75rem;
      border: 1px solid #334155; background: #1e293b; color: #e2e8f0; font-size: 0.95rem;
      outline: none; transition: border-color 0.2s; }
    .compose input[type="text"]:focus { border-color: var(--accent); }
    .compose input[type="text"]::placeholder { color: #475569; }
    .compose button { padding: 0.75rem 1.5rem; border-radius: 0.75rem; border: none;
      background: var(--accent); color: white; font-weight: 600; font-size: 0.95rem;
      cursor: pointer; transition: opacity 0.2s; white-space: nowrap; }
    .compose button:hover { opacity: 0.85; }
    .compose button:disabled { opacity: 0.4; cursor: not-allowed; }
    .clear-btn { padding: 0.75rem; border-radius: 0.75rem; border: 1px solid #334155;
      background: #1e293b; font-size: 1rem; cursor: pointer; transition: border-color 0.2s; }
    .clear-btn:hover { border-color: #ef4444; }
    .messages { display: flex; flex-direction: column; gap: 0.6rem; }
    .msg { background: #1e293b; border: 1px solid #334155; border-radius: 0.75rem;
      padding: 0.85rem 1rem; display: flex; justify-content: space-between;
      align-items: flex-start; gap: 1rem; }
    .msg.new { animation: slideIn 0.3s ease-out; }
    @keyframes slideIn { from { opacity: 0; transform: translateY(-8px); }
      to { opacity: 1; transform: translateY(0); } }
    .msg-text { font-size: 0.95rem; line-height: 1.5; word-break: break-word; }
    .msg-meta { font-size: 0.7rem; color: #475569; white-space: nowrap; padding-top: 0.15rem; }
    .empty { text-align: center; color: #475569; padding: 3rem 1rem; font-size: 0.95rem; }
    footer { width: 100%; text-align: center; padding: 1.5rem; color: #334155; font-size: 0.75rem; }
    footer code { color: var(--accent); }
  </style>
</head>
<body>
  <header>
    <h1>📮 {{ .Name }} — Message Wall</h1>
    <p>A tiny app running in Kubernetes — powered by Tilt + Rancher Desktop</p>
    <div class="info-bar">
      <div class="info-pill"><span class="dot"></span> <span id="pod">—</span></div>
      <div class="info-pill">⏱ Uptime: <span id="uptime">—</span></div>
      <div class="info-pill">💬 <span id="count">0</span> messages</div>
      ${cacheEnabled ? '<div class="info-pill"><span class="dot"></span> Redis cache</div>' : ''}
      ${username ? `<div class="info-pill">🔐 ${username} <a href="/logout" style="margin-left:0.4rem;color:#ef4444;text-decoration:none;font-weight:600" title="Logout">✕</a></div>` : ''}
    </div>
  </header>

  <main>
    <form class="compose" onsubmit="send(event)">
      <input type="text" id="input" placeholder="Say something…" autocomplete="off" maxlength="280" autofocus />
      <button type="submit" id="btn">Post</button>
      <button type="button" onclick="clear_()" class="clear-btn" title="Delete all messages">🧹</button>
    </form>
    <div class="messages" id="messages"></div>
  </main>

  <footer>
    Change <code>ACCENT_COLOR</code> in src/index.js → save → see it update here ✨
  </footer>

  <script>
    const msgBox = document.getElementById('messages');
    const input  = document.getElementById('input');
    const btn    = document.getElementById('btn');
    const podEl  = document.getElementById('pod');
    const upEl   = document.getElementById('uptime');
    const cntEl  = document.getElementById('count');
    let knownIds = new Set();

    function timeAgo(ts) {
      const s = Math.floor((Date.now() - new Date(ts).getTime()) / 1000);
      if (s < 60)   return s + 's ago';
      if (s < 3600) return Math.floor(s / 60) + 'm ago';
      if (s < 86400) return Math.floor(s / 3600) + 'h ago';
      return Math.floor(s / 86400) + 'd ago';
    }
    function fmtUptime(s) {
      if (s < 60)   return Math.floor(s) + 's';
      if (s < 3600) return Math.floor(s / 60) + 'm ' + Math.floor(s % 60) + 's';
      return Math.floor(s / 3600) + 'h ' + Math.floor((s % 3600) / 60) + 'm';
    }
    function esc(t) { const d = document.createElement('div'); d.textContent = t; return d.innerHTML; }

    async function load() {
      try {
        const r = await fetch('/api/messages');
        const d = await r.json();
        podEl.textContent = d.pod;
        upEl.textContent  = fmtUptime(d.uptime);
        cntEl.textContent = d.total;
        if (!d.messages.length) {
          msgBox.innerHTML = '<div class="empty">No messages yet — be the first! 🎉</div>';
          knownIds.clear(); return;
        }
        const currentIds  = d.messages.map(m => m.id).join(',');
        const previousIds = [...msgBox.querySelectorAll('.msg')].map(e => e.dataset.id).join(',');
        if (currentIds !== previousIds) {
          msgBox.innerHTML = d.messages.map(m => {
            const isNew = !knownIds.has(m.id);
            return '<div class="msg' + (isNew ? ' new' : '') + '" data-id="' + m.id + '">' +
              '<span class="msg-text">' + esc(m.body) + '</span>' +
              '<span class="msg-meta">' + timeAgo(m.created_at) + '</span>' +
            '</div>';
          }).join('');
        } else {
          msgBox.querySelectorAll('.msg').forEach((el, i) => {
            el.querySelector('.msg-meta').textContent = timeAgo(d.messages[i].created_at);
          });
        }
        knownIds = new Set(d.messages.map(m => m.id));
      } catch (e) {
        msgBox.innerHTML = '<div class="empty">⚠️ Cannot reach API</div>';
      }
    }

    async function send(e) {
      e.preventDefault();
      const body = input.value.trim();
      if (!body) return;
      btn.disabled = true;
      try {
        await fetch('/api/messages', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ body }),
        });
        input.value = '';
        await load();
      } finally { btn.disabled = false; }
      input.focus();
    }

    async function clear_() {
      if (!confirm('Delete all messages?')) return;
      await fetch('/api/messages', { method: 'DELETE' });
      knownIds.clear();
      await load();
    }

    window._appLoad = load;
    load();
    setInterval(load, 3000);
  </script>
</body>
</html>`};


const startTime = Date.now();

// Connect to Postgres with bounded retries — postgres often isn't
// Ready when the app pod starts (helm install kicks both in parallel,
// the postgres init scripts take 5-15s). A failed connect that exits
// the process gets us into a CrashLoop with k8s recreating us before
// postgres comes up, AND with `node --watch` (the dev process from
// rda's web-nodejs Procfile) the script just *waits* on connect
// failure instead of exiting — so the readiness probe never gets a
// healthy response and the pod gets killed anyway. Retrying gives
// postgres time to finish init while we keep the process alive.
// ─── OIDC server-side helpers (browser cookie flow + Bearer) ────

function appBaseURL(req) {
  // Honour X-Forwarded-Proto from the Ingress controller. Falls back
  // to http (Tilt's local dev).
  const proto = req.headers['x-forwarded-proto'] || 'http';
  return `${proto}://${req.headers.host}`;
}

function parseCookies(cookieHeader) {
  if (!cookieHeader) return {};
  const out = {};
  for (const c of cookieHeader.split(';')) {
    const [k, ...rest] = c.trim().split('=');
    if (k) out[k] = rest.join('=');
  }
  return out;
}

function setCookie(res, name, value, opts = {}) {
  const parts = [`${name}=${value}`, 'Path=/', 'HttpOnly', 'SameSite=Lax'];
  if (opts.maxAge !== undefined) parts.push(`Max-Age=${opts.maxAge}`);
  if (opts.secure) parts.push('Secure');
  // Append to any existing Set-Cookie (Node lets you pass an array).
  const prev = res.getHeader('Set-Cookie');
  const cookie = parts.join('; ');
  res.setHeader('Set-Cookie', prev ? [].concat(prev, cookie) : cookie);
}

function clearCookie(res, name) {
  setCookie(res, name, '', { maxAge: 0 });
}

// Initialise the JWKS keyset on first use. Lazy because jose's import
// + JWKS fetch are non-trivial; only pay the cost when /admin or
// /auth/callback fires for the first time.
async function getJWKS() {
  if (!AUTH_URL || !AUTH_ISSUER || !OIDC_CLIENT_ID) return null;
  if (jwksFetcher) return jwksFetcher;
  if (!jose) jose = await import('jose');
  // JWKS URI uses the in-cluster URL (pod-reachable) even though the
  // OIDC discovery's jwks_uri claims the browser-facing one — same
  // keys served at <issuer>/keys whichever URL gets us there.
  jwksFetcher = jose.createRemoteJWKSet(new URL(`${AUTH_URL}/keys`));
  return jwksFetcher;
}

// Validate a JWT against the configured issuer + audience.  Returns
// the decoded payload on success; throws on any failure (signature,
// expiry, issuer mismatch, audience mismatch).
async function verifyIDToken(rawJWT) {
  const jwks = await getJWKS();
  if (!jwks) throw new Error('OIDC not configured');
  if (!jose) jose = await import('jose');
  const { payload } = await jose.jwtVerify(rawJWT, jwks, {
    issuer: AUTH_ISSUER,
    audience: OIDC_CLIENT_ID,
  });
  return payload;
}

// Extract the id_token from cookie OR Authorization: Bearer header.
// Returns { token, source } or { token: '' } if neither is present.
function extractIDToken(req) {
  const cookies = parseCookies(req.headers.cookie);
  if (cookies[SESSION_COOKIE_NAME]) {
    return { token: cookies[SESSION_COOKIE_NAME], source: 'cookie' };
  }
  const auth = req.headers.authorization || '';
  if (auth.startsWith('Bearer ')) {
    return { token: auth.slice('Bearer '.length), source: 'bearer' };
  }
  return { token: '', source: '' };
}

async function connectWithRetry(maxAttempts, delayMs) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      await client.connect();
      return;
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      console.log(
        `⏳ postgres not ready yet (attempt ${attempt}/${maxAttempts}: ${err.code || err.message}); retrying in ${delayMs}ms…`
      );
      await new Promise(r => setTimeout(r, delayMs));
    }
  }
}

// Postgres is OPTIONAL. If <DB_PREFIX>_HOST is unset (no postgres binding),
// the Message Wall API is disabled and the home page shows a friendly
// 'no DB bound' placeholder. /metrics, /health, /ready still work.
const dbEnabled = !!process.env[`${dbPrefix}_HOST`];

// ─── Redis cache (optional) ─────────────────────
// Reads <CACHE_BINDING>_HOST from the binding-secret. Default binding
// name is "cache"; override via CACHE_BINDING=<name>.
const cachePrefix = (process.env.CACHE_BINDING || 'CACHE').toUpperCase().replace(/-/g, '_');
const cacheHost = process.env[`${cachePrefix}_HOST`] || '';
const cachePort = process.env[`${cachePrefix}_PORT`] || '6379';
const cachePass = process.env[`${cachePrefix}_PASSWORD`] || '';
const cacheEnabled = !!cacheHost;
let redisClient = null;

async function start() {
  if (!dbEnabled) {
    console.log(`ℹ️  No ${dbPrefix}_HOST in env — postgres binding not configured; serving placeholder.`);
    console.log(`   To enable Message Wall: rda add-service postgresql ${dbPrefix.toLowerCase()}, flip enabled:true, fill auth slots.`);
  } else {
    await connectWithRetry(60, 2000);   // up to 60 attempts × 2s = 2min budget
    console.log('✅ Connected to PostgreSQL at ' + env('HOST') + ':' + env('PORT', '5432'));

    await client.query(`
      CREATE TABLE IF NOT EXISTS messages (
        id         SERIAL PRIMARY KEY,
        body       TEXT NOT NULL CHECK (char_length(body) <= 280),
        created_at TIMESTAMPTZ DEFAULT NOW()
      )
    `);
    console.log('✅ Table ready');

    const { rows: [{ count }] } = await client.query('SELECT COUNT(*) FROM messages');
    messagesCurrent.set(parseInt(count));
  }

  // Redis connection (optional)
  if (cacheEnabled) {
    try {
      const net = require('net');
      const sock = new net.Socket();
      await new Promise((resolve, reject) => {
        sock.connect(parseInt(cachePort), cacheHost, () => { sock.destroy(); resolve(); });
        sock.on('error', reject);
        sock.setTimeout(3000, () => { sock.destroy(); reject(new Error('timeout')); });
      });
      console.log(`✅ Redis reachable at ${cacheHost}:${cachePort}`);
    } catch (err) {
      console.log(`⚠️  Redis at ${cacheHost}:${cachePort} not reachable: ${err.message}`);
    }
  } else {
    console.log(`ℹ️  No ${cachePrefix}_HOST in env — redis cache not configured.`);
  }

  let endSessionEndpoint = '';
  if (AUTH_URL) {
    try {
      const resp = await fetch(AUTH_URL + '/.well-known/openid-configuration');
      const doc = await resp.json();
      if (doc.end_session_endpoint) {
        endSessionEndpoint = doc.end_session_endpoint;
        console.log('🔐 OIDC end_session_endpoint: ' + endSessionEndpoint);
      } else {
        console.log('ℹ️  OIDC provider has no end_session_endpoint (logout will clear cookie only)');
      }
    } catch (err) {
      console.log('⚠️  OIDC discovery failed: ' + err.message + ' (logout will clear cookie only)');
    }
  }

  const server = http.createServer(async (req, res) => {
    const end = httpDuration.startTimer();
    let status = 200;
    try {
      if (req.method === 'GET' && req.url === '/') {
        // Server-side auth gate: when OIDC is configured, redirect to
        // /login if there's no session cookie. Makes the home page
        // gated identically to /admin — deterministic and independent
        // of the browser-side oidc-client-ts JS (which can fail
        // silently if the CDN is blocked or localStorage is stale).
        //
        // When OIDC isn't configured (no auth binding) the home page
        // stays public — the Message Wall demo is meant to be
        // readable without auth in that mode.
        if (AUTH_URL && AUTH_ISSUER && OIDC_CLIENT_ID) {
          const cookies = parseCookies(req.headers.cookie);
          if (!cookies[SESSION_COOKIE_NAME]) {
            res.writeHead(302, { Location: '/login' });
            res.end();
            end({ method: 'GET', path: '/', status: 302 });
            return;
          }
        }
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(html(req));
        end({ method: 'GET', path: '/', status: 200 });
        return;
      }
      if (req.method === 'GET' && req.url === '/metrics') {
        const metrics = await promClient.register.metrics();
        res.writeHead(200, { 'Content-Type': promClient.register.contentType });
        res.end(metrics);
        return; // don't pollute the histogram with /metrics noise
      }

      // ── OIDC: /login → /auth/callback → /admin (browser cookie)
      //         /admin (Bearer too — same verify, no cookie needed)
      //         /logout
      if (req.url === '/login' || req.url.startsWith('/login?')) {
        if (!AUTH_URL || !AUTH_ISSUER || !OIDC_CLIENT_ID) {
          res.writeHead(503, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'oidc not configured', hint: 'set AUTH_BINDING + bind dex via rda add-service dex auth' }));
          end({ method: req.method, path: '/login', status: 503 });
          return;
        }
        if (!OIDC_CLIENT_SECRET) {
          res.writeHead(503, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            error: 'OIDC_CLIENT_SECRET unset',
            hint: 'required for browser flow (the staticClient secret in dex passthrough); set via suse-library.env or project from a Secret',
          }));
          end({ method: req.method, path: '/login', status: 503 });
          return;
        }
        const state = crypto.randomBytes(16).toString('hex');
        setCookie(res, STATE_COOKIE_NAME, state, { maxAge: 600 });
        const redirectURI = appBaseURL(req) + '/auth/callback';
        const params = new URLSearchParams({
          response_type: 'code',
          client_id: OIDC_CLIENT_ID,
          redirect_uri: redirectURI,
          scope: 'openid profile email',
          state: state,
        });
        res.writeHead(302, { Location: AUTH_PUBLIC_URL + '/auth?' + params.toString() });
        res.end();
        end({ method: req.method, path: '/login', status: 302 });
        return;
      }

      if (req.url.startsWith('/auth/callback')) {
        const u = new URL(req.url, appBaseURL(req));
        const cookies = parseCookies(req.headers.cookie);
        const expectedState = cookies[STATE_COOKIE_NAME];
        if (!expectedState) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: `missing ${STATE_COOKIE_NAME} cookie — start at /login` }));
          end({ method: req.method, path: '/auth/callback', status: 400 });
          return;
        }
        if (u.searchParams.get('state') !== expectedState) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'state mismatch — possible CSRF' }));
          end({ method: req.method, path: '/auth/callback', status: 400 });
          return;
        }
        const code = u.searchParams.get('code');
        if (!code) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'missing code query param' }));
          end({ method: req.method, path: '/auth/callback', status: 400 });
          return;
        }
        try {
          // Exchange code → tokens via the IN-CLUSTER URL (AUTH_URL).
          const tokenResp = await fetch(AUTH_URL + '/token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
              grant_type: 'authorization_code',
              code: code,
              redirect_uri: appBaseURL(req) + '/auth/callback',
              client_id: OIDC_CLIENT_ID,
              client_secret: OIDC_CLIENT_SECRET,
            }),
          });
          if (!tokenResp.ok) {
            const body = await tokenResp.text();
            throw new Error(`token endpoint returned ${tokenResp.status}: ${body}`);
          }
          const tokens = await tokenResp.json();
          if (!tokens.id_token) throw new Error('no id_token in token response');
          // Defence in depth — verify before trusting.
          await verifyIDToken(tokens.id_token);
          // Cookie matches the dex default 1h token life.
          clearCookie(res, STATE_COOKIE_NAME);
          setCookie(res, SESSION_COOKIE_NAME, tokens.id_token, { maxAge: 3600 });
          res.writeHead(302, { Location: '/' });
          res.end();
          end({ method: req.method, path: '/auth/callback', status: 302 });
          return;
        } catch (err) {
          res.writeHead(502, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: err.message }));
          end({ method: req.method, path: '/auth/callback', status: 502 });
          return;
        }
      }

      if (req.url === '/logout') {
        // Capture the id_token BEFORE clearing the cookie — needed as
        // id_token_hint for RP-Initiated Logout at the IdP.
        const cookies = parseCookies(req.headers.cookie);
        const rawIDToken = cookies[SESSION_COOKIE_NAME] || '';
        clearCookie(res, SESSION_COOKIE_NAME);
        // If OIDC is configured, perform RP-Initiated Logout against
        // dex's end_session_endpoint so the IdP session is terminated
        // too — not just the local cookie.
        if (endSessionEndpoint && rawIDToken) {
          const params = new URLSearchParams({
            id_token_hint: rawIDToken,
            post_logout_redirect_uri: appBaseURL(req) + '/',
          });
          res.writeHead(302, { Location: endSessionEndpoint + '?' + params.toString() });
          res.end();
          end({ method: req.method, path: '/logout', status: 302 });
          return;
        }
        res.writeHead(302, { Location: '/' });
        res.end();
        end({ method: req.method, path: '/logout', status: 302 });
        return;
      }

      if (req.url === '/admin') {
        if (!AUTH_URL || !AUTH_ISSUER || !OIDC_CLIENT_ID) {
          res.writeHead(503, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'oidc not configured' }));
          end({ method: req.method, path: '/admin', status: 503 });
          return;
        }
        const { token, source } = extractIDToken(req);
        if (!token) {
          res.writeHead(401, {
            'Content-Type': 'application/json',
            'WWW-Authenticate': `Bearer realm="${AUTH_ISSUER}"`,
          });
          res.end(JSON.stringify({
            error: 'unauthenticated — no Bearer header AND no session cookie',
            hint: 'GET /login to start the browser flow, OR send Authorization: Bearer <jwt>',
            issuer: AUTH_ISSUER,
          }));
          end({ method: req.method, path: '/admin', status: 401 });
          return;
        }
        try {
          const claims = await verifyIDToken(token);
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            authenticated: true,
            source,
            subject: claims.sub,
            issuer: claims.iss,
            audience: claims.aud,
            expires_at: claims.exp,
            claims,
          }, null, 2));
          end({ method: req.method, path: '/admin', status: 200 });
          return;
        } catch (err) {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'id_token verification failed: ' + err.message, source }));
          end({ method: req.method, path: '/admin', status: 401 });
          return;
        }
      }

      if (req.url === '/api/messages') {
        if (!dbEnabled) {
          status = 503;
          res.writeHead(503, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            error: 'messages api unavailable: no postgres binding configured',
            hint: 'rda add-service postgresql ' + dbPrefix.toLowerCase() + ', flip enabled:true, fill auth slots',
          }));
          end({ method: req.method, path: '/api/messages', status: 503 });
          return;
        }
      }
      if (req.method === 'GET' && req.url === '/api/messages') {
        const { rows } = await client.query(
          'SELECT id, body, created_at FROM messages ORDER BY created_at DESC LIMIT 50'
        );
        const { rows: [{ count }] } = await client.query('SELECT COUNT(*) FROM messages');
        const total = parseInt(count);
        messagesCurrent.set(total);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          messages: rows, total,
          pod: process.env.HOSTNAME || 'local',
          uptime: (Date.now() - startTime) / 1000,
        }));
        end({ method: 'GET', path: '/api/messages', status: 200 });
        return;
      }
      if (req.method === 'POST' && req.url === '/api/messages') {
        const chunks = [];
        for await (const chunk of req) chunks.push(chunk);
        const { body } = JSON.parse(Buffer.concat(chunks).toString());
        if (!body || !body.trim()) {
          status = 400;
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'body is required' }));
          end({ method: 'POST', path: '/api/messages', status: 400 });
          return;
        }
        const { rows } = await client.query(
          'INSERT INTO messages (body) VALUES ($1) RETURNING id, body, created_at',
          [body.trim().slice(0, 280)]
        );
        messagesPosted.inc();
        messagesCurrent.inc();
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(rows[0]));
        end({ method: 'POST', path: '/api/messages', status: 201 });
        return;
      }
      if (req.method === 'DELETE' && req.url === '/api/messages') {
        await client.query('DELETE FROM messages');
        messagesDeleted.inc();
        messagesCurrent.set(0);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ deleted: true }));
        end({ method: 'DELETE', path: '/api/messages', status: 200 });
        return;
      }
      if (req.url === '/ready') {
        if (!dbEnabled) {
          // No DB to probe; report ready as long as the process is up.
          res.writeHead(200); res.end('ready');
          end({ method: req.method, path: '/ready', status: 200 });
          return;
        }
        try {
          await client.query('SELECT 1');
          res.writeHead(200); res.end('ready');
          end({ method: req.method, path: '/ready', status: 200 });
        } catch (err) {
          res.writeHead(503); res.end('not-ready: ' + err.message);
          end({ method: req.method, path: '/ready', status: 503 });
        }
        return;
      }
      if (req.url === '/health') {
        res.writeHead(200); res.end('ok');
        end({ method: req.method, path: '/health', status: 200 });
        return;
      }
      status = 404;
      res.writeHead(404); res.end('Not found');
      end({ method: req.method, path: req.url, status: 404 });
    } catch (err) {
      console.error('❌', err.message);
      status = 500;
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
      end({ method: req.method, path: req.url, status: 500 });
    }
  });

  server.listen(PORT, () => {
    console.log('🚀 Server running on http://localhost:' + PORT);
    console.log('📊 Metrics at http://localhost:' + PORT + '/metrics');
    if (AUTH_PUBLIC_URL) console.log('🔐 OIDC: ' + AUTH_PUBLIC_URL);
  });
}

start().catch(err => {
  console.error('💀 Failed to start:', err.message);
  process.exit(1);
});
